  ingredients:{es:['Semax · spray nasal 0.1% (más común) o polvo + agua bacteriostática','Pipeta o spray nasal pequeño','Refrigerar'],en:['Semax · 0.1% nasal spray (most common) or powder + bacteriostatic water','Pipette or small nasal spray','Refrigerate']},
